<?php
require_once "config/db.php";$pageTitle='Attendance';
if($_SERVER['REQUEST_METHOD']==='POST'){$member=(int)($_POST['member_id']??0);$day=$_POST['attendance_date']??date('Y-m-d');try{$st=$pdo->prepare("INSERT INTO attendance(member_id,attendance_date,check_in) SELECT id,?,CURTIME() FROM members WHERE id=? AND status='Active'");$st->execute([$day,$member]);if($st->rowCount())$_SESSION['flash']=['type'=>'success','message'=>'Attendance marked.'];else $_SESSION['flash']=['type'=>'error','message'=>'Member not found or attendance already exists.'];}catch(PDOException $e){$_SESSION['flash']=['type'=>'error','message'=>'This member already has attendance for that date.'];}header("Location: attendance.php");exit;}
$day=$_GET['date']??date('Y-m-d');$q=trim($_GET['q']??'');$active=$pdo->query("SELECT id,name FROM members WHERE status='Active' ORDER BY name")->fetchAll();$st=$pdo->prepare("SELECT a.*,m.name,m.phone FROM attendance a JOIN members m ON m.id=a.member_id WHERE a.attendance_date=? AND (m.name LIKE ? OR m.phone LIKE ?) ORDER BY a.check_in DESC");$st->execute([$day,"%$q%","%$q%"]);$rows=$st->fetchAll();require "includes/header.php";
?><div class="page-intro"><div><h1>Daily attendance</h1><p>Record gym check-ins and track visits by date.</p></div></div><section class="panel"><div class="panel-head"><div><h3>Mark attendance</h3><p>A member can be checked in once per day.</p></div><span class="tag">CHECK-IN DESK</span></div><form method="post" class="form-grid"><div class="field"><label>Active member *</label><select name="member_id" required><option value="">Select member</option><?php foreach($active as $m): ?><option value="<?= $m['id'] ?>"><?= htmlspecialchars($m['name']) ?></option><?php endforeach; ?></select></div><div class="field"><label>Attendance date *</label><input type="date" name="attendance_date" value="<?= htmlspecialchars($day) ?>" max="<?= date('Y-m-d') ?>" required></div><div class="field field-action"><button class="btn btn-primary">✓ Mark present</button></div></form></section><section class="panel"><div class="panel-head"><div><h3>Attendance records <span class="count"><?= count($rows) ?></span></h3><p>Check-ins for selected date.</p></div></div><form class="toolbar"><input name="q" value="<?= htmlspecialchars($q) ?>" placeholder="Search member or phone"><input type="date" name="date" value="<?= htmlspecialchars($day) ?>" max="<?= date('Y-m-d') ?>"><button class="btn btn-secondary">Search</button></form><div class="table-wrap"><table><thead><tr><th>MEMBER</th><th>PHONE</th><th>DATE</th><th>CHECK-IN</th><th>STATUS</th></tr></thead><tbody><?php foreach($rows as $a): ?><tr><td><?= htmlspecialchars($a['name']) ?></td><td><?= htmlspecialchars($a['phone']) ?></td><td><?= htmlspecialchars($a['attendance_date']) ?></td><td><?= htmlspecialchars($a['check_in']) ?></td><td><span class="status active">Present</span></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="5" class="empty">No attendance found for this date.</td></tr><?php endif; ?></tbody></table></div></section><?php require "includes/footer.php"; ?>